import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Repo visibility is derived from the dep closure, not chosen per-repo","description":"","frontmatter":{"title":"Repo visibility is derived from the dep closure, not chosen per-repo","type":"adr","date":"2026-10-21T00:00:00.000Z","status":"accepted","status_note":"Accepted"},"headers":[],"relativePath":"handl/project/adrs/0150-visibility-closure-model.md","filePath":"vendored/handl/project/adrs/0150-visibility-closure-model.md"}`),a={name:`handl/project/adrs/0150-visibility-closure-model.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0150-repo-visibility-is-derived-from-the-dep-closure-not-chosen-per-repo" tabindex="-1">ADR-0150: Repo visibility is derived from the dep closure, not chosen per-repo <a class="header-anchor" href="#adr-0150-repo-visibility-is-derived-from-the-dep-closure-not-chosen-per-repo" aria-label="Permalink to “ADR-0150: Repo visibility is derived from the dep closure, not chosen per-repo”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The org splits one-crate-per-repo (ADR-0128), which makes repo visibility a graph property: a public repo&#39;s <code>git</code> deps must resolve anonymously, so every repo in its transitive <code>cargo metadata</code> closure must also be public. Visibility was historically set ad hoc — repos went public or private without checking who still referenced them, which left the public <code>research-mlopt</code> unable to <code>cargo build</code> for outsiders (its closure reached private repos).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>A repo is public iff it sits in the dep closure of a public seed repo</strong> (<code>research-mlopt</code> today). Visibility is <em>derived</em>, never chosen per-repo. Two rules keep the derived set honest:</p><ol><li><strong>Edges point private → public.</strong> An adapter or tool binding lives in the repo of the tool it serves, never in the library crate — otherwise a public library drags private tooling into its closure. (<code>HandlNativeLint</code> moved from <code>plugin-lib-handl</code> to <code>plugin-ext-lint</code> under this rule.)</li><li><strong>The closure is checked, not remembered.</strong><code>research-mlopt/scripts/check_public_closure.sh</code> fails if any <code>handl-lang/*</code> git source in its lockfiles resolves to a private repo. Run it after touching dep edges.</li></ol><h3 id="split-applied-under-this-rule" tabindex="-1">Split applied under this rule <a class="header-anchor" href="#split-applied-under-this-rule" aria-label="Permalink to “Split applied under this rule”">​</a></h3><p><code>handl-kit-data-prelude</code> split into:</p><ul><li><strong><code>handl-kit-prelude-lang</code></strong> (public, new repo <code>kit-prelude-lang</code>) — the eval-path fragment set (<code>tokens</code>, <code>grammar</code>, <code>eval</code>, <code>types</code>, <code>ast</code>, <code>caps</code>, <code>options</code>, <code>lexer_rules</code>, <code>transforms</code>, <code>globals</code>) + <code>language_from_yaml</code> / <code>language_from_dir</code> / <code>merge_lang_fragments</code> / <code>merge_lints</code> / <code>merge_lsp</code>. This is the canonical <code>Language</code> minus the tooling sections — the dep a lex/parse/eval consumer needs.</li><li><strong><code>handl-kit-data-prelude</code></strong> (private) — the composition wrapper: composes <code>kit-prelude-lang</code>&#39;s language, merges <code>lints.yaml</code> + <code>lsp.yaml</code> on top, keeps <code>data/kits/*</code> and the <code>DataKit</code> machinery. All 77 tests pass unchanged; the composed <code>Language</code> is identical.</li></ul><h3 id="tier-model" tabindex="-1">Tier model <a class="header-anchor" href="#tier-model" aria-label="Permalink to “Tier model”">​</a></h3><table tabindex="0"><thead><tr><th>tier</th><th>contents</th><th>visibility</th></tr></thead><tbody><tr><td>substrate</td><td><code>kernel</code>, <code>engine</code> bases, <code>engine-*-impl</code> that are load-bearing (<code>-pattern</code>, <code>-pratt</code>, <code>-tree-walk</code>, <code>-bytecode</code>, <code>-rewrite</code>, <code>-typecheck</code>), <code>.hnl</code> eval deps (<code>lib-desugar</code>, <code>lib-loader</code>, <code>lib-str-handl</code>, <code>lib-char{,-native}</code>), <code>host</code>, <code>host-tensor</code>, <code>kit-prelude-lang</code></td><td>public at launch</td></tr><tr><td>research</td><td><code>research-mlopt</code>, <code>egraph</code>, <code>discovery</code></td><td>public</td></tr><tr><td>surface</td><td><code>docs</code>, <code>slidev-theme</code></td><td>public</td></tr><tr><td>tooling</td><td><code>engine-lint</code>, <code>engine-fmt</code>, <code>engine-test</code>, <code>ext-*</code>, <code>host-cli</code>, <code>host-lsp</code>, <code>kit-*</code>, remaining <code>lib-*</code> ports</td><td>private until done</td></tr></tbody></table><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>engine-lint</code> leaves the mlopt closure permanently (adapter moved).</li><li><code>engine-exec-bytecode</code> / <code>engine-typecheck</code> stay in the closure — the <code>.hnl</code> loader runs on bytecode, and <code>handl-runtime</code> re-exports the <code>TypecheckEngine</code> interface. Both are substrate, not severable; they flip public at launch.</li><li>Eight private repos remain in the closure today (<code>lib-desugar</code>, <code>lib-loader</code>, <code>lib-str-handl</code>, <code>lib-char</code>, <code>lib-char-native</code>, <code>engine-transform-rewrite</code>, <code>engine-exec-bytecode</code>, <code>engine-typecheck</code>) — a single visibility flip each, no code change.</li><li>Public repos&#39; <code>cargo test</code> may still pull private dev-deps; the public guarantee is <code>cargo build</code>.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};